// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.integrityimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — No-op integrity token verifier (Module 12, Pillar 1). * * Strategy §12.1 — the **default** [IntegrityTokenVerifier] implementation * that always returns [IntegrityCheckState.Verified]. Real impl requires * Play Integrity API setup in Google Play Console (cloud project + signing * certificate enrollment) and is wired in by the production app. * * ## Why a no-op default? * * Play Integrity setup requires: *   1. A Google Cloud project with the Play Integrity API enabled. *   2. The app's signing certificate SHA-256 enrolled in Play Console. *   3. A Google Play Services account on the test device. *   4. Network access to play.googleapis.com. * * In dev/test/forked-Android environments where any of the above are * unavailable, NOUS uses this no-op verifier so the app doesn't crash or * refuse to start. The real verifier is installed via Hilt override in the * production app module (e.g., `:app` provides a `RealPlayIntegrityVerifier` * that hits the Google Play Console endpoint). * * Production callers SHOULD additionally call * [ZeroTrustIntegrityManager.verifyIntegrity] before trusting the no-op * verdict — the no-op bypasses only the JWT issuance, not the SupplyChainMonitor. * * @see IntegrityTokenVerifier */fun interface IntegrityTokenVerifier {    /**     * Verify a Play Integrity token (or skip verification in the no-op case).     *     * @param jwt the Play Integrity JWT returned by     *   `IntegrityTokenResponse.token()`, or `null` to skip API call.     * @return the integrity check state.     */    fun verify(jwt: String?): IntegrityCheckState}/** * Default no-op implementation — always returns [IntegrityCheckState.Verified]. * * @see IntegrityTokenVerifier */@Singletonclass NoOpIntegrityTokenVerifier @Inject constructor() : IntegrityTokenVerifier {    override fun verify(jwt: String?): IntegrityCheckState =        IntegrityCheckState.Verified(requestHash = null)}